// shared model, used by every page
const byId=Object.fromEntries(N.map(n=>[n[0],{id:n[0],label:n[1],src:n[2],mine:!!n[3],ft:n[4],aroma:n[5],cross:n[6],url:n[7],breeder:n[8]||''}]));
const par={},kids={};E.forEach(([c,p,k])=>{(par[c]=par[c]||[]).push({p,k:k||'cross'});(kids[p]=kids[p]||[]).push(c)});
const mine=N.filter(n=>n[3]).map(n=>n[0]);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
